import Foundation

// swiftlint:disable line_length
@MainActor
final class MockGradesService: GradesServiceProtocol {
    func fetchGradeBook() async throws -> GradeBook {
//        try await Task.sleep(for: .milliseconds(900))
        let data = Data(Self.mockJSON.utf8)
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        let dtos = try decoder.decode([GradeBookResponseDTO].self, from: data)
        guard let dto = dtos.first else { throw APIError.invalidResponse }
        return dto.toDomain()
    }
}

